snippet_css:
:root{
  --bg: #E6F7FF;
  --fg: #0B3A53;
  --muted: #2E6B8A;
  --surface: rgba(255,255,255,.78);
  --border: rgba(255,255,255,.95);
  --accent: #1B9FD8;
  --accent-fg: #05293B;
  --focus-ring: #0F6E99;
  --radius: 22px;
  --radius-sm: 14px;
  --shadow: 0 10px 24px rgba(27,159,216,.20),inset 0 1px 0 rgba(255,255,255,.9);
  --btn-shadow: 0 6px 0 rgba(27,159,216,.35);
  --art-bg: linear-gradient(180deg,#BEEBFF,#5FD1E8 55%,#8FE3C0);
  --media-bg: linear-gradient(180deg,#E8FAFF,#A8E6F5);
  --cta-bg: linear-gradient(180deg,#D6F3FF,#B6E9F8);
  --input-bg: rgba(255,255,255,.92);
  --ok: #1E9E6A;
  --warn: #D9614A;
  --font-display: 'Varela Round',sans-serif;
  --font-body: 'Nunito Sans','Noto Sans TC',sans-serif;
}

